## 1. COMPREENSÃO DO PROBLEMA

É preciso manter uma sequência dinâmica e responder consultas sobre um intervalo: quantas subsequências contíguas desse intervalo têm GCD maior que 1.

A entrada contém `N`, `M`, os `N` valores iniciais e, depois, `M` operações de atualização ou consulta. Para cada consulta, deve ser impressa uma contagem. Como essa contagem pode chegar a `N(N+1)/2`, ela deve usar 64 bits.

Os valores são positivos e podem chegar a `10^9`. Não há casos com valores negativos ou `N = 0`; para `N = 1`, a resposta é 1 se o elemento for maior que 1 e 0 caso contrário.

## 2. PLANEJAMENTO E DESIGN ALGORÍTMICO

Usaremos uma árvore de segmentos. Cada nó guarda:

- o GCD de todo o intervalo;
- o número de subsequências candidatas no intervalo;
- os GCDs de todos os prefixos, agrupados por GCD igual, com a quantidade de prefixos em cada grupo;
- os GCDs dos sufixos, agrupados da mesma forma.

Ao combinar dois nós, as subsequências candidatas que atravessam a fronteira são formadas por um sufixo do nó esquerdo e um prefixo do nó direito. Para cada par de grupos, basta verificar se o GCD dos dois GCDs é maior que 1.

Cada lista de prefixos ou sufixos tem no máximo 30 grupos: os GCDs distintos formam uma cadeia de divisibilidade e cada redução estrita diminui o valor pelo menos pela metade. Há também um atalho: se os menores GCDs maiores que 1 dos dois lados têm GCD maior que 1, todos os pares desses grupos são candidatos.

**Complexidade:** uma combinação custa `O(G²)` no pior caso, em que `G ≤ 30`; a árvore usa `O(NG)` de memória. Construção, atualizações e consultas fazem `O(log N)` combinações cada. As contagens são armazenadas em `long long`.

## 3. CODIFICAÇÃO EM C

```c
#include <stdio.h>
#include <stdlib.h>

#define MAX_GROUPS 31

typedef struct {
    int gcd_value;
    int count;
} Group;

typedef struct {
    int left_child;
    int right_child;

    int len;
    int all_gcd;
    long long good;

    int prefix_count;
    int suffix_count;
    Group prefix[MAX_GROUPS];
    Group suffix[MAX_GROUPS];
} Node;

static Node *tree;
static int nodes_used;

static int gcd_int(int a, int b) {
    while (b != 0) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

/* Copia apenas o resumo, preservando os índices dos filhos do destino. */
static void copy_summary(Node *dst, const Node *src) {
    dst->len = src->len;
    dst->all_gcd = src->all_gcd;
    dst->good = src->good;
    dst->prefix_count = src->prefix_count;
    dst->suffix_count = src->suffix_count;

    for (int i = 0; i < src->prefix_count; ++i)
        dst->prefix[i] = src->prefix[i];

    for (int i = 0; i < src->suffix_count; ++i)
        dst->suffix[i] = src->suffix[i];
}

static void append_group(Group *groups, int *count, int value, int amount) {
    if (*count > 0 && groups[*count - 1].gcd_value == value) {
        groups[*count - 1].count += amount;
    } else if (*count < MAX_GROUPS) {
        groups[*count].gcd_value = value;
        groups[*count].count = amount;
        ++(*count);
    }
}

/* Combina os resumos de dois intervalos adjacentes, left seguido de right. */
static void merge_nodes(Node *out, const Node *left, const Node *right) {
    if (left->len == 0) {
        copy_summary(out, right);
        return;
    }
    if (right->len == 0) {
        copy_summary(out, left);
        return;
    }

    out->len = left->len + right->len;
    out->all_gcd = gcd_int(left->all_gcd, right->all_gcd);
    out->good = left->good + right->good;

    /* Candidatas que cruzam a fronteira: sufixo esquerdo + prefixo direito. */
    int last_left = -1;
    int last_right = -1;

    for (int i = 0; i < left->suffix_count; ++i) {
        if (left->suffix[i].gcd_value > 1)
            last_left = i;
    }
    for (int i = 0; i < right->prefix_count; ++i) {
        if (right->prefix[i].gcd_value > 1)
            last_right = i;
    }

    if (last_left >= 0 && last_right >= 0) {
        int common = gcd_int(left->suffix[last_left].gcd_value,
                             right->prefix[last_right].gcd_value);

        if (common > 1) {
            long long left_amount = 0;
            long long right_amount = 0;

            for (int i = 0; i <= last_left; ++i)
                left_amount += left->suffix[i].count;
            for (int i = 0; i <= last_right; ++i)
                right_amount += right->prefix[i].count;

            out->good += left_amount * right_amount;
        } else {
            for (int i = 0; i <= last_left; ++i) {
                int x = left->suffix[i].gcd_value;
                for (int j = 0; j <= last_right; ++j) {
                    int y = right->prefix[j].gcd_value;
                    if (gcd_int(x, y) > 1) {
                        out->good += (long long)left->suffix[i].count
                                   * right->prefix[j].count;
                    }
                }
            }
        }
    }

    /* Prefixos: prefixos inteiramente à esquerda e os que entram à direita. */
    out->prefix_count = 0;
    for (int i = 0; i < left->prefix_count; ++i) {
        append_group(out->prefix, &out->prefix_count,
                     left->prefix[i].gcd_value, left->prefix[i].count);
    }
    for (int i = 0; i < right->prefix_count; ++i) {
        int value = gcd_int(left->all_gcd, right->prefix[i].gcd_value);
        append_group(out->prefix, &out->prefix_count,
                     value, right->prefix[i].count);
    }

    /* Sufixos: sufixos inteiramente à direita e os que entram à esquerda. */
    out->suffix_count = 0;
    for (int i = 0; i < right->suffix_count; ++i) {
        append_group(out->suffix, &out->suffix_count,
                     right->suffix[i].gcd_value, right->suffix[i].count);
    }
    for (int i = 0; i < left->suffix_count; ++i) {
        int value = gcd_int(right->all_gcd, left->suffix[i].gcd_value);
        append_group(out->suffix, &out->suffix_count,
                     value, left->suffix[i].count);
    }
}

static int build(int lo, int hi, const int *values) {
    int id = ++nodes_used;
    Node *node = &tree[id];

    if (lo == hi) {
        int value = values[lo];
        node->len = 1;
        node->all_gcd = value;
        node->good = (value > 1) ? 1 : 0;

        node->prefix_count = 1;
        node->prefix[0].gcd_value = value;
        node->prefix[0].count = 1;

        node->suffix_count = 1;
        node->suffix[0].gcd_value = value;
        node->suffix[0].count = 1;
    } else {
        int mid = (lo + hi) / 2;
        node->left_child = build(lo, mid, values);
        node->right_child = build(mid + 1, hi, values);

        merge_nodes(node,
                    &tree[node->left_child],
                    &tree[node->right_child]);
    }

    return id;
}

static void update(int id, int lo, int hi, int position, int value) {
    Node *node = &tree[id];

    if (lo == hi) {
        node->len = 1;
        node->all_gcd = value;
        node->good = (value > 1) ? 1 : 0;

        node->prefix_count = 1;
        node->prefix[0].gcd_value = value;
        node->prefix[0].count = 1;

        node->suffix_count = 1;
        node->suffix[0].gcd_value = value;
        node->suffix[0].count = 1;
        return;
    }

    int mid = (lo + hi) / 2;
    if (position <= mid)
        update(node->left_child, lo, mid, position, value);
    else
        update(node->right_child, mid + 1, hi, position, value);

    merge_nodes(node,
                &tree[node->left_child],
                &tree[node->right_child]);
}

/* Retorna 1 se houver interseção com o intervalo consultado. */
static int query(int id, int lo, int hi, int ql, int qr, Node *result) {
    if (ql <= lo && hi <= qr) {
        *result = tree[id];
        return 1;
    }

    int mid = (lo + hi) / 2;
    int left_id = tree[id].left_child;
    int right_id = tree[id].right_child;

    if (qr <= mid)
        return query(left_id, lo, mid, ql, qr, result);

    if (ql > mid)
        return query(right_id, mid + 1, hi, ql, qr, result);

    Node left_result, right_result;
    query(left_id, lo, mid, ql, qr, &left_result);
    query(right_id, mid + 1, hi, ql, qr, &right_result);
    merge_nodes(result, &left_result, &right_result);
    return 1;
}

int main(void) {
    int n, m;

    if (scanf("%d %d", &n, &m) != 2)
        return 0;

    int *values = (int *)malloc((size_t)(n + 1) * sizeof(int));
    if (values == NULL)
        return 0;

    for (int i = 1; i <= n; ++i)
        scanf("%d", &values[i]);

    /* Uma árvore binária cheia com n folhas tem 2n - 1 nós. */
    tree = (Node *)calloc((size_t)(2 * n + 1), sizeof(Node));
    if (tree == NULL) {
        free(values);
        return 0;
    }

    int root = build(1, n, values);

    for (int op = 0; op < m; ++op) {
        int type, a, b;
        scanf("%d %d %d", &type, &a, &b);

        if (type == 1) {
            update(root, 1, n, a, b);
        } else {
            Node result;
            query(root, 1, n, a, b, &result);
            printf("%lld\n", result.good);
        }
    }

    free(tree);
    free(values);
    return 0;
}
```

## 4. RETROSPECTO E VERIFICAÇÃO

A estrutura conta cada subsequência exatamente uma vez: ela está inteiramente no filho esquerdo, inteiramente no direito ou cruza a fronteira entre eles. No último caso, o GCD da subsequência é maior que 1 precisamente quando o GCD entre o GCD do sufixo esquerdo e o do prefixo direito é maior que 1.

Para `N = 1`, a folha produz diretamente a resposta correta. Valores iguais a 1 não contribuem para a contagem. O uso de `long long` evita overflow nas contagens.

O resumo de cada nó tem no máximo 30 grupos de GCDs distintos; a implementação reserva 31 posições por segurança. A árvore é armazenada com `2N - 1` nós, evitando o custo de uma árvore iterativa dimensionada para a próxima potência de dois.

